//! A tabela estática da matriz capability × provider/superfície (22 colunas × 18 capabilities).
//!
//! Mantida à mão: cada célula cita o código, o teste ou a fixture que a sustenta. Onde não há prova
//! (`Unknown`), diz o que falta provar. O doc `docs/ade-ags/HARNESS_CONTRATO.md` §1 explica e espelha a
//! contagem; um teste confere que os dois concordam. Onde a matriz corrige um inventário de colega, o doc
//! registra a divergência.
//!
//! Quem muda uma célula atualiza o doc. A UI, o IPC e o MCP ainda não leem esta tabela.

use super::capability::{Capability, Cell, Claim, Proof, ProviderMatrix, Scope, Surface};

const fn sup(capability: Capability, scope: Scope, proof: Proof, evidence: &'static [&'static str], note: &'static str) -> Cell {
    Cell { capability, claim: Claim::supported(scope, proof, evidence, note) }
}

const fn unsup(capability: Capability, scope: Scope, proof: Proof, evidence: &'static [&'static str], note: &'static str) -> Cell {
    Cell { capability, claim: Claim::unsupported(scope, proof, evidence, note) }
}

const fn unk(
    capability: Capability,
    scope: Scope,
    proof: Proof,
    evidence: &'static [&'static str],
    missing: &'static str,
    note: &'static str,
) -> Cell {
    Cell { capability, claim: Claim::unknown(scope, proof, evidence, missing, note) }
}

const fn claim_sup(scope: Scope, proof: Proof, evidence: &'static [&'static str], note: &'static str) -> Claim {
    Claim::supported(scope, proof, evidence, note)
}

const fn claim_unsup(scope: Scope, proof: Proof, evidence: &'static [&'static str], note: &'static str) -> Claim {
    Claim::unsupported(scope, proof, evidence, note)
}

const fn claim_unk(scope: Scope, proof: Proof, evidence: &'static [&'static str], missing: &'static str, note: &'static str) -> Claim {
    Claim::unknown(scope, proof, evidence, missing, note)
}

